import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createHalEngine} from '../config.js';
import type {HalEngineConfig} from '../config.js';
import {createServer} from './createServer.js';
import type {HalServerOptions} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {answeringOrchestrator, deferred} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import type {SessionStore, SessionSummary} from '../types/sessionStore.js';
import {setLogger} from '../shared/logger.js';

// Real WebSocket connections driving list_conversations through createServer and createHalEngine.

interface WireSummary {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
  title?: string;
}

interface WireFrame {
  type: string;
  sessionId?: string;
  conversations?: WireSummary[];
  hasMore?: boolean;
  code?: string;
  message?: string;
  timestamp?: number;
  index?: number;
  delta?: string;
}

const servers: Array<{wss: {clients: Set<WebSocket>}; stop: () => Promise<void>}> = [];
const clients: WebSocket[] = [];

const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

beforeAll(() => {
  setLogger({debug: () => undefined, info: () => undefined, warn: () => undefined, error: () => undefined});
});

afterAll(() => {
  setLogger();
});

afterEach(async () => {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    await eventually(() => hal.wss.clients.size === 0);
    await hal.stop();
  }
});

const startServer = async (
  sessionStore: SessionStore,
  options: Record<string, unknown> = {},
  orchestrator: ChatOrchestrator = answeringOrchestrator
) => {
  const auth = {userId: 'u1'};
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: auth.userId}),
    sessionStore,
    orchestrator,
    ...options,
  } as unknown as HalServerOptions);
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return {auth, url: `ws://127.0.0.1:${port}/hal/ws`};
};

const connectSocket = async (url: string): Promise<{client: WebSocket; sessionId: string; frames: WireFrame[]}> => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  const frames: WireFrame[] = [];
  const sessionId = await new Promise<string>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      frames.push(frame);
      if (frame.type === 'connected') resolve(frame.sessionId ?? '');
    });
  });
  return {client, sessionId, frames};
};

const sendAndWaitPong = async (
  client: WebSocket,
  frames: WireFrame[],
  payload: unknown,
  marker: number
): Promise<WireFrame[]> => {
  const before = frames.length;
  client.send(JSON.stringify(payload));
  client.send(JSON.stringify({type: 'ping', timestamp: marker}));
  await eventually(() => frames.slice(before).some(frame => frame.type === 'pong' && frame.timestamp === marker));
  return frames.slice(before).filter(frame => !(frame.type === 'pong' && frame.timestamp === marker));
};

const delegatingStore = (inner: InMemorySessionStore): SessionStore => ({
  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
  get: sessionId => inner.get(sessionId),
  delete: sessionId => inner.delete(sessionId),
  count: () => inner.count(),
  clear: () => inner.clear(),
});

describe('delivering a user conversation list over the websocket protocol', () => {
  it('answers list_conversations for the socket user in newest-first order, preserves store titles, and pages with limit and before across hasMore', async () => {
    const base = new InMemorySessionStore();
    for (const [id, user, at] of [
      ['c1', 'u1', '2026-09-30T08:00:00.000Z'],
      ['c2', 'u1', '2026-09-30T09:00:00.000Z'],
      ['c3', 'u1', '2026-09-30T10:00:00.000Z'],
      ['other', 'u2', '2026-09-30T11:00:00.000Z'],
    ] as const) {
      const session = base.create(id, user);
      session.entries.push({role: 'user', content: `msg ${id}`, timestamp: at});
    }
    const store: SessionStore = {
      ...delegatingStore(base),
      listFor: (userId, options) =>
        base
          .listFor(userId, options)
          .filter(row => row.entryCount > 0)
          .map(row =>
            row.sessionId === 'c3'
              ? ({...row, title: 'Quarterly review'} as SessionSummary)
              : row
          ),
    };
    const {url} = await startServer(store, {conversationList: {enabled: true}});
    const {client, frames} = await connectSocket(url);

    const [page1] = await sendAndWaitPong(client, frames, {type: 'list_conversations', limit: 2, userId: 'u2'}, 1);
    const cursor = page1?.conversations?.[1];
    const [page2] = await sendAndWaitPong(
      client,
      frames,
      {
        type: 'list_conversations',
        limit: 2,
        before: {updatedAt: cursor?.updatedAt, sessionId: cursor?.sessionId},
      },
      2
    );

    expect({
      firstIds: page1?.conversations?.map(row => row.sessionId),
      firstHasMore: page1?.hasMore,
      firstTitle: page1?.conversations?.[0]?.title,
      secondTitlePresent: 'title' in (page1?.conversations?.[1] ?? {}),
      isoTimestamps:
        typeof page1?.conversations?.[0]?.createdAt === 'string' &&
        typeof page1?.conversations?.[0]?.updatedAt === 'string',
      secondIds: page2?.conversations?.map(row => row.sessionId),
      secondHasMore: page2?.hasMore,
    }).toEqual({
      firstIds: ['c3', 'c2'],
      firstHasMore: true,
      firstTitle: 'Quarterly review',
      secondTitlePresent: false,
      isoTimestamps: true,
      secondIds: ['c1'],
      secondHasMore: false,
    });
  });

  it('caps limit at 100, defaults to 20, and answers a request while a turn streams without taking the session lock', async () => {
    const store = new InMemorySessionStore();
    for (let i = 0; i < 110; i++) {
      const id = `s-${String(i).padStart(3, '0')}`;
      const session = store.create(id, 'u1');
      session.entries.push({
        role: 'user',
        content: `question ${i}`,
        timestamp: new Date(Date.parse('2026-09-30T08:00:00.000Z') + i * 1000).toISOString(),
      });
    }
    const gate = deferred();
    const pausingOrchestrator: ChatOrchestrator = {
      processMessage: async () => 'answer',
      async *processMessageStream(): AsyncGenerator<MessageChunk> {
        yield {type: 'text', text: 'streaming'};
        await gate.until;
        yield {type: 'stop', stopReason: 'end_turn'};
      },
    };
    const {url} = await startServer(store, {conversationList: {enabled: true}}, pausingOrchestrator);
    const {client, frames} = await connectSocket(url);

    const [defaultList] = await sendAndWaitPong(client, frames, {type: 'list_conversations'}, 10);
    const [zeroList] = await sendAndWaitPong(client, frames, {type: 'list_conversations', limit: 0}, 11);
    client.send(JSON.stringify({type: 'user_message', content: 'start turn'}));
    await eventually(() => frames.some(frame => frame.type === 'entry_delta'));
    const [midStreamList] = await sendAndWaitPong(client, frames, {type: 'list_conversations', limit: 150}, 12);
    const endedBeforeRelease = frames.some(frame => frame.type === 'stream_end');
    gate.release();
    await eventually(() => frames.some(frame => frame.type === 'stream_end'));

    expect({
      defaultCount: defaultList?.conversations?.length,
      defaultHasMore: defaultList?.hasMore,
      zeroFrame: zeroList,
      cappedCount: midStreamList?.conversations?.length,
      cappedHasMore: midStreamList?.hasMore,
      endedBeforeRelease,
    }).toEqual({
      defaultCount: 20,
      defaultHasMore: true,
      zeroFrame: {type: 'conversation_list', conversations: [], hasMore: false},
      cappedCount: 100,
      cappedHasMore: true,
      endedBeforeRelease: false,
    });
  });

  it('derives an eighty-character preview title from the first non-empty user message when preview is on and createHalEngine forwards transport.conversationList', async () => {
    const store = new InMemorySessionStore();
    const longLine = `   First   line   with   extra   spaces   and   more   words   to   exceed   eighty   characters   easily   here\nSecond line ignored`;
    const withLong = store.create('long-user', 'u1');
    withLong.entries.push({role: 'user', content: longLine, timestamp: '2026-09-30T10:00:00.000Z'});
    const emptyFirst = store.create('empty-first', 'u1');
    emptyFirst.entries.push(
      {role: 'user', content: '   \n\t  ', timestamp: '2026-09-30T09:00:00.000Z'},
      {role: 'user', content: 'Actual question\nwith newline', timestamp: '2026-09-30T09:01:00.000Z'}
    );
    const noUser = store.create('no-user', 'u1');
    noUser.entries.push({
      role: 'assistant',
      content: 'Welcome!',
      timestamp: '2026-09-30T08:00:00.000Z',
      isStreaming: false,
    });
    const engine = createHalEngine({
      provider: {type: 'mock'},
      prompt: {identity: 'test'},
      auth: {ws: async () => ({id: 'u1'})},
      session: store,
      transport: {port: 0, conversationList: {enabled: true, preview: true}},
    } as unknown as HalEngineConfig);
    await engine.start(0);
    servers.push(engine);
    const {port} = engine.server.address() as AddressInfo;
    const {client, frames} = await connectSocket(`ws://127.0.0.1:${port}/hal/ws`);

    const [listed] = await sendAndWaitPong(client, frames, {type: 'list_conversations'}, 20);
    const byId = new Map((listed?.conversations ?? []).map(row => [row.sessionId, row]));
    client.close();
    await once(client, 'close');

    const normalizedFirstLine =
      'First line with extra spaces and more words to exceed eighty characters easily here';
    expect({
      longTitle: byId.get('long-user')?.title,
      longLength: byId.get('long-user')?.title?.length,
      skippedBlank: byId.get('empty-first')?.title,
      noUserHasTitle: 'title' in (byId.get('no-user') ?? {}),
    }).toEqual({
      longTitle: normalizedFirstLine.slice(0, 80),
      longLength: 80,
      skippedBlank: 'Actual question',
      noUserHasTitle: false,
    });
  });

  it('rejects a malformed limit or before cursor with INVALID_MESSAGE and no stream_end', async () => {
    const {url} = await startServer(new InMemorySessionStore(), {conversationList: {enabled: true}});
    const {client, frames} = await connectSocket(url);

    const badRequests = [
      {type: 'list_conversations', limit: -1},
      {type: 'list_conversations', limit: 1.5},
      {type: 'list_conversations', limit: '10'},
      {type: 'list_conversations', before: 'not-an-object'},
      {type: 'list_conversations', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_conversations', before: {updatedAt: '2026-09-30T08:00:00.000Z', sessionId: ''}},
    ];
    const responses: WireFrame[][] = [];
    for (const [index, bad] of badRequests.entries()) {
      responses.push(await sendAndWaitPong(client, frames, bad, 30 + index));
    }

    expect(responses).toEqual(
      badRequests.map(() => [{type: 'error', code: 'INVALID_MESSAGE', message: expect.any(String)}])
    );
  });

  it('answers INVALID_MESSAGE when conversationList is off or listFor is absent, and SERVER_ERROR when listFor throws, with no stream_end', async () => {
    const inner = new InMemorySessionStore();
    const disabled = await startServer(inner);
    const noListFor = await startServer(delegatingStore(inner), {conversationList: {enabled: true}});
    const throwing = await startServer(
      {
        ...delegatingStore(inner),
        listFor: () => {
          throw new Error('database unreachable');
        },
      },
      {conversationList: {enabled: true}}
    );

    const Outcomes: Record<string, WireFrame[]> = {};
    for (const [name, target] of Object.entries({disabled, noListFor, throwing})) {
      const {client, frames} = await connectSocket(target.url);
      Outcomes[name] = await sendAndWaitPong(client, frames, {type: 'list_conversations'}, 40);
    }

    expect(Outcomes).toEqual({
      disabled: [{type: 'error', code: 'INVALID_MESSAGE', message: expect.any(String)}],
      noListFor: [{type: 'error', code: 'INVALID_MESSAGE', message: expect.any(String)}],
      throwing: [{type: 'error', code: 'SERVER_ERROR', message: expect.any(String)}],
    });
  });
});

